corrected_code:
@router.delete("/jobs/transcode-queue/{task_id}")
async def cancel_transcode_task(
    task_id: str,
    worker_pool: TranscodeWorkerPool = Depends(get_worker_pool),
    current_user: User = Depends(get_current_user)
):
    task = worker_pool.get_queued_task(task_id)
    if not task:
        raise HTTPException(status_code=404, detail="Queued task not found")
    if task.owner_id != current_user.id and not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: cannot cancel another user's worker task")
    task.cancel()
    return {"status": "cancelled", "task_id": task_id}
